(function () {
  var aa = {
    base: function () { return pm.variables.replaceIn('{{base_url}}'); },
    tokenOf: function (html) {
      var m = html.match(/name=["']csrfmiddlewaretoken["'][^>]*value=["']([^"']+)["']/);
      return m ? m[1] : '';
    },
    get: function (path, cb) {
      pm.sendRequest({ url: aa.base() + path, method: 'GET' }, function (e, r) { cb(r); });
    },
    post: function (path, fields, cb) {
      var body = Object.keys(fields).map(function (k) { return { key: k, value: fields[k] }; });
      pm.sendRequest({ url: aa.base() + path, method: 'POST', body: { mode: 'urlencoded', urlencoded: body } }, function (e, r) { cb(r); });
    },
    // lấy CSRF mới của trang path và lưu vào biến csrf_token
    token: function (path, cb) {
      aa.get(path, function (r) { pm.collectionVariables.set('csrf_token', aa.tokenOf(r.text())); if (cb) { cb(); } });
    },
    // đưa phiên về Guest (đăng xuất nếu đang đăng nhập), rồi lấy CSRF của trang path
    guest: function (path, cb) {
      aa.get('/accounts/password/change/', function (r) {
        aa.post('/accounts/logout/', { csrfmiddlewaretoken: aa.tokenOf(r.text()) }, function () {
          if (path) { aa.token(path, cb); } else if (cb) { cb(); }
        });
      });
    },
    // đăng nhập bằng user/pass từ trạng thái Guest, rồi lấy CSRF của trang path
    login: function (user, pass, path, cb) {
      aa.guest('/accounts/login/', function () {
        aa.post('/accounts/login/', { csrfmiddlewaretoken: pm.collectionVariables.get('csrf_token'), username: user, password: pass }, function () {
          if (path) { aa.token(path, cb); } else if (cb) { cb(); }
        });
      });
    },
    user: function (path) { aa.login(pm.variables.get('aa_username'), pm.variables.get('aa_password'), path); },
    admin: function (path) { aa.login(pm.variables.get('admin_user'), pm.variables.get('admin_pass'), path); }
  };
  return aa;
})()
